// Runtime validation (valibot) for server data, and the source of the JSON Schemas in schema/*.json
// (generated by `bun run schema`; flx-app validates its PHP output against them).
// Objects are loose: unknown keys pass, so the server can add fields without breaking older apps.
// A bad module is dropped (the app opens its web fallback); a bad config falls back to the app default.
import * as v from 'valibot';
import type { AppConfig, Bootstrap } from './types/config';
import type { Manifest, ManifestBundle } from './types/manifest';

const str = v.string();
const opt = <T extends v.GenericSchema>(s: T) => v.optional(s);
const tpl = v.pipe(v.string(), v.maxLength(2000));
const id = v.pipe(v.string(), v.regex(/^[\w-]+$/));
const target = v.pipe(v.string(), v.minLength(1), v.maxLength(500));
const color = v.pipe(v.string(), v.regex(/^(#[0-9a-fA-F]{3,8}|rgba?\([\d\s.,%]+\))$/));
const tone = v.picklist(['default', 'accent', 'ok', 'warn', 'danger', 'muted', 'info']);
const options = v.union([
  v.array(v.looseObject({ value: str, label: str })),
  v.looseObject({ source: str, path: str, value: str, label: str }),
]);

// ---- conditions ----
const op = v.picklist(['eq', 'ne', 'in', 'nin', 'gt', 'gte', 'lt', 'lte', 'filled', 'empty', 'truthy', 'falsy']);
export const ConditionSchema: v.GenericSchema = v.union([
  v.looseObject({ path: str, op, value: opt(v.unknown()) }),
  v.looseObject({ all: v.array(v.lazy(() => ConditionSchema)) }),
  v.looseObject({ any: v.array(v.lazy(() => ConditionSchema)) }),
  v.looseObject({ not: v.lazy(() => ConditionSchema) }),
]);
const when = opt(ConditionSchema);

const NavigateSchema = v.looseObject({ target, params: opt(v.record(str, v.union([tpl, v.number(), v.boolean()]))) });

// ---- sources ----
export const PagingSchema = v.looseObject({
  mode: v.picklist(['page', 'wp', 'cursor', 'none']),
  param: opt(str),
  size_param: opt(str),
  size: opt(v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(200))),
  items: opt(str),
  total: opt(str),
  pages: opt(str),
  next: opt(str),
});

export const SourceSchema = v.looseObject({
  path: v.pipe(tpl, v.minLength(1), v.check((p) => !/^[a-z][a-z0-9+.-]*:|^\/\//i.test(p), 'path must be relative to /wp-json/')),
  method: opt(v.picklist(['GET', 'POST'])),
  query: opt(v.record(str, v.union([str, v.number(), v.boolean()]))),
  body: opt(v.nullable(v.record(str, v.unknown()))),
  paging: opt(PagingSchema),
  key: opt(str),
  cache: opt(v.looseObject({ stale: opt(v.number()), persist: opt(v.boolean()) })),
  poll: opt(v.union([v.literal(0), v.pipe(v.number(), v.minValue(10))])),
});

// ---- list / detail building blocks ----
const AvatarSchema = v.looseObject({ image: opt(tpl), text: opt(tpl) });
const BadgeSchema = v.looseObject({ text: tpl, tone: opt(tone), when });
const ChipsSchema = v.looseObject({ path: str, text: tpl, color: opt(tpl) });

export const ListItemSchema = v.looseObject({
  title: tpl,
  subtitle: opt(tpl),
  meta: opt(tpl),
  caption: opt(tpl),
  avatar: opt(AvatarSchema),
  badges: opt(v.array(BadgeSchema)),
  chips: opt(ChipsSchema),
  image: opt(tpl),
  unread: opt(v.union([str, ConditionSchema])),
});

const ScreenActionsSchema = v.looseObject({
  header: opt(v.array(str)),
  row: opt(v.array(str)),
  bulk: opt(v.array(str)),
  fab: opt(str),
  footer: opt(v.array(str)),
});

const FIELD_TYPES = [
  'text', 'textarea', 'email', 'phone', 'url', 'number', 'money', 'switch', 'select', 'multiselect', 'radio', 'segmented',
  'date', 'datetime', 'time', 'color', 'image', 'file', 'markdown', 'user', 'post', 'term', 'tags', 'hidden', 'readonly', 'secret', 'repeater',
] as const;

export const FormFieldSchema = v.looseObject({
  name: v.pipe(str, v.regex(/^[\w-]+(\.[\w-]+)*$/)),
  type: v.picklist(FIELD_TYPES),
  label: str,
  placeholder: opt(str),
  help: opt(str),
  required: opt(v.boolean()),
  min: opt(v.number()),
  max: opt(v.number()),
  minLength: opt(v.number()),
  maxLength: opt(v.number()),
  pattern: opt(v.pipe(str, v.maxLength(200))),
  default: opt(v.unknown()),
  options: opt(options),
  when,
  width: opt(v.picklist(['full', 'half'])),
  readonly_when: when,
  creatable: opt(v.boolean()),
  load: opt(str),
  upload: opt(v.pipe(str, v.maxLength(200))),
  taxonomy: opt(v.pipe(str, v.regex(/^[\w-]+$/))),
  multiple: opt(v.boolean()),
});

const sectionBase = { title: opt(str), when };
export const SectionSchema = v.variant('type', [
  v.looseObject({ type: v.literal('fields'), ...sectionBase, fields: v.array(v.looseObject({ label: str, value: tpl, link: opt(tpl), copy: opt(v.boolean()), when })) }),
  v.looseObject({ type: v.literal('stats'), ...sectionBase, items: v.array(v.looseObject({ label: str, value: tpl, sub: opt(tpl), tone: opt(tone), when, onPress: opt(NavigateSchema) })) }),
  v.looseObject({ type: v.literal('chips'), ...sectionBase, path: str, text: tpl, color: opt(tpl), add: opt(str), remove: opt(str) }),
  v.looseObject({ type: v.literal('timeline'), ...sectionBase, path: str, item: v.looseObject({ title: tpl, body: opt(tpl), at: opt(tpl), label: opt(tpl), link: opt(tpl) }) }),
  v.looseObject({ type: v.literal('list'), ...sectionBase, path: str, item: ListItemSchema, onPress: opt(NavigateSchema) }),
  v.looseObject({ type: v.literal('content'), ...sectionBase, value: tpl, format: opt(v.picklist(['markdown', 'html', 'text'])) }),
  v.looseObject({ type: v.literal('actions'), ...sectionBase, items: v.array(str) }),
  v.looseObject({ type: v.literal('notice'), ...sectionBase, tone: opt(tone), text: tpl }),
]);

const RequestSchema = v.looseObject({
  method: opt(v.picklist(['GET', 'POST', 'PUT', 'PATCH', 'DELETE'])),
  path: tpl,
  body: opt(v.nullable(v.record(str, v.unknown()))),
  path_create: opt(tpl),
  path_update: opt(tpl),
});

const AfterSchema = v.looseObject({
  toast: opt(str),
  back: opt(v.boolean()),
  navigate: opt(NavigateSchema),
  refresh: opt(v.boolean()),
  invalidate: opt(v.array(str)),
  merge: opt(v.boolean()),
});

// ---- screens ----
const screenBase = { title: opt(tpl), when };
export const ScreenSchema = v.variant('type', [
  v.looseObject({
    type: v.literal('list'),
    ...screenBase,
    source: str,
    layout: opt(v.picklist(['rows', 'cards', 'grid', 'table'])),
    columns: opt(v.array(v.looseObject({ label: str, value: tpl, width: opt(v.number()), align: opt(v.picklist(['start', 'end'])) }))),
    search: opt(v.looseObject({ param: str, placeholder: opt(str) })),
    filters: opt(v.array(v.looseObject({ param: str, label: str, type: v.picklist(['select', 'toggle', 'segmented']), options: opt(options) }))),
    sort: opt(v.looseObject({ param: str, order_param: opt(str), options: v.array(v.looseObject({ value: str, label: str })) })),
    group_by: opt(str),
    item: ListItemSchema,
    onPress: opt(NavigateSchema),
    actions: opt(ScreenActionsSchema),
    empty: opt(v.looseObject({ title: opt(str), body: opt(str), icon: opt(str) })),
    refresh: opt(v.boolean()),
  }),
  v.looseObject({
    type: v.literal('detail'),
    ...screenBase,
    source: str,
    header: opt(v.looseObject({ title: tpl, subtitle: opt(tpl), avatar: opt(AvatarSchema), chips: opt(ChipsSchema), quick: opt(v.array(str)) })),
    sections: v.array(SectionSchema),
    actions: opt(ScreenActionsSchema),
  }),
  v.looseObject({
    type: v.literal('form'),
    ...screenBase,
    load: opt(str),
    fields: v.array(FormFieldSchema),
    submit: RequestSchema,
    validate: opt(v.looseObject({ any_of: opt(v.array(str)), message: opt(str) })),
    after: opt(AfterSchema),
    dirty_guard: opt(v.boolean()),
  }),
  v.looseObject({ type: v.literal('dashboard'), ...screenBase, sources: opt(v.array(str)), sections: v.array(SectionSchema) }),
  v.looseObject({ type: v.literal('settings'), ...screenBase, option: str, fields: v.array(FormFieldSchema) }),
  v.looseObject({ type: v.literal('content'), ...screenBase, source: str, format: opt(v.picklist(['markdown', 'html'])), path: opt(str) }),
  v.looseObject({ type: v.literal('tabs'), ...screenBase, tabs: v.array(v.looseObject({ screen: str, title: str })) }),
  v.looseObject({ type: v.literal('native'), ...screenBase, component: id, params: opt(v.record(str, tpl)), fallback: opt(v.looseObject({ web: str })) }),
  v.looseObject({ type: v.literal('web'), ...screenBase, path: str }),
]);

export const ActionSchema = v.looseObject({
  label: str,
  icon: opt(str),
  tone: opt(tone),
  can: opt(str),
  when,
  confirm: opt(v.looseObject({ title: str, body: opt(str), ok: opt(str) })),
  prompt: opt(v.nullable(v.looseObject({ title: str, fields: v.array(FormFieldSchema) }))),
  request: opt(RequestSchema),
  navigate: opt(NavigateSchema),
  web: opt(tpl),
  open: opt(tpl),
  share: opt(v.looseObject({ text: opt(tpl), url: opt(tpl) })),
  copy: opt(tpl),
  native: opt(v.looseObject({ component: id, params: opt(v.record(str, tpl)) })),
  refresh: opt(v.boolean()),
  after: opt(AfterSchema),
  optimistic: opt(v.nullable(v.looseObject({ path: opt(str), value: opt(v.unknown()), remove: opt(v.literal('item')) }))),
  haptic: opt(v.picklist(['success', 'warning', 'error', 'light'])),
});

const ManifestObject = v.looseObject({
  schema: v.literal('flx-app-manifest/1'),
  id,
  plugin: opt(str),
  version: opt(str),
  min_app: opt(str),
  title: str,
  icon: opt(str),
  icon_url: opt(str),
  menu: opt(str),
  entry: str,
  tabs: opt(v.array(str)),
  can: opt(v.record(str, v.boolean())),
  routes: opt(v.record(str, v.looseObject({ screen: str, params: opt(v.record(str, str)) }))),
  sources: v.record(str, SourceSchema),
  screens: v.record(str, ScreenSchema),
  actions: opt(v.record(str, ActionSchema)),
  fallback: opt(v.looseObject({ web: str })),
  search: opt(v.looseObject({ source: str, param: str, item: ListItemSchema, onPress: opt(NavigateSchema) })),
  push: opt(v.looseObject({ events: v.array(v.looseObject({ id: str, title: str, default: opt(v.boolean()) })) })),
});

/** Cross-references the JSON Schema cannot express (entry/source/action ids exist). */
export const ManifestSchema = v.pipe(
  ManifestObject,
  v.check((m) => !!m.screens[m.entry], 'entry screen missing'),
  v.check((m) => Object.values(m.screens).every((s) => !('source' in s) || !!m.sources[s.source as string]), 'screen source missing'),
  v.check(
    (m) =>
      Object.values(m.screens).every((s) => {
        const a = (s as { actions?: Record<string, unknown> }).actions;
        const ids = a ? Object.values(a).flatMap((x) => (Array.isArray(x) ? x : typeof x === 'string' ? [x] : [])) : [];
        return ids.every((x) => !!m.actions?.[x as string]);
      }),
    'screen action missing',
  ),
);

export const ManifestBundleSchema = v.looseObject({ hash: opt(str), modules: v.record(str, v.unknown()) });

// ---- config ----
const colors = v.partial(
  v.looseObject({
    primary: color, onPrimary: color, accent: color, bg: color, surface: color, surface2: color, border: color,
    text: color, textMuted: color, danger: color, warning: color, success: color, info: color,
  }),
);

export const ThemeSchema = v.looseObject({
  mode: opt(v.picklist(['system', 'light', 'dark'])),
  light: opt(colors),
  dark: opt(colors),
  radius: opt(v.picklist(['small', 'medium', 'large'])),
  density: opt(v.picklist(['compact', 'comfortable'])),
  font: opt(v.looseObject({ body: opt(str), heading: opt(str), files: opt(v.nullable(v.record(str, str))) })),
});

export const ShellSchema = v.looseObject({
  nav: v.picklist(['tabs', 'drawer', 'tabs+drawer']),
  home: target,
  tabs: v.pipe(v.array(v.looseObject({ id: str, target, icon: opt(str), label: opt(str), badge: opt(str) })), v.maxLength(5)),
  drawer: v.looseObject({
    enabled: v.boolean(),
    header: v.picklist(['account', 'brand', 'none']),
    pins: opt(v.array(target)),
    groups: v.array(v.looseObject({ id: str, label: opt(str), collapsed: opt(v.boolean()), items: v.array(target) })),
    footer: v.array(target),
  }),
  topbar: v.looseObject({
    style: v.picklist(['large', 'compact']),
    show_logo: v.boolean(),
    site_switcher: v.boolean(),
    actions: v.array(v.looseObject({ target, icon: opt(str), label: opt(str) })),
  }),
});

export const ConfigSchema = v.looseObject({
  schema: v.literal('flx-app-config/1'),
  hash: opt(str),
  brand: opt(v.looseObject({ name: opt(str), short_name: opt(str), logo: opt(str), logo_dark: opt(str), icon: opt(str) })),
  theme: opt(ThemeSchema),
  shell: ShellSchema,
  features: opt(v.looseObject({ web_session: opt(v.boolean()), push: opt(v.boolean()), otp: opt(v.boolean()), search: opt(v.boolean()), biometric_lock: opt(v.boolean()) })),
  transport: opt(v.looseObject({ method_override: opt(v.boolean()), poll_min: opt(v.pipe(v.number(), v.minValue(10))), token_header: opt(v.picklist(['authorization', 'x-fluxwp-token'])) })),
  webview: opt(v.looseObject({ allow_hosts: opt(v.array(str)), external: opt(v.picklist(['in_app_browser', 'system'])) })),
  links: opt(v.looseObject({ privacy: opt(str), support: opt(str) })),
  versions: opt(v.record(str, str)),
});

export const BootstrapSchema = v.looseObject({
  schema: opt(v.literal('flx-app-bootstrap/1')),
  site: v.looseObject({ name: str, url: str, description: opt(str), admin_url: opt(str), rest_url: opt(str), icon: opt(str), locale: opt(str), timezone: opt(str), https: opt(v.boolean()) }),
  auth: v.looseObject({
    methods: v.array(v.picklist(['oauth', 'otp', 'apikey', 'apppass'])),
    clients: opt(v.looseObject({ mobile: opt(str), desktop: opt(str) })),
    redirects: opt(v.looseObject({ mobile: opt(v.array(str)), desktop: opt(v.array(str)), loopback_any_port: opt(v.boolean()) })),
    authorize: opt(str),
    login_url: opt(str),
    token: opt(str),
    revoke: opt(str),
    scopes: opt(v.array(str)),
    pkce: opt(v.literal('S256')),
    prompt_login: opt(v.boolean()),
    otp: opt(v.looseObject({ start: opt(str), verify: opt(str) })),
  }),
  apps: opt(
    v.looseObject({
      generic: opt(v.boolean()),
      clients: opt(v.array(v.looseObject({ id: str, name: str, platform: v.picklist(['mobile', 'desktop']) }))),
      preset: opt(v.nullable(str)),
      store: opt(v.record(str, str)),
    }),
  ),
  brand: opt(v.looseObject({ name: opt(str), short_name: opt(str), logo: opt(str), logo_dark: opt(str), icon: opt(str) })),
  theme: opt(v.looseObject({ mode: opt(v.picklist(['system', 'light', 'dark'])), light: opt(colors), dark: opt(colors) })),
  packages: opt(v.array(v.looseObject({ slug: str, name: str, type: v.picklist(['plugin', 'theme']) }))),
  min_app: opt(str),
  min_app_desktop: opt(str),
  flx_app: opt(str),
  api: opt(str),
  endpoints: opt(v.record(str, str)),
});

/** brands/<slug>/brand.json (desktop core keys + mobile keys, plan §11.1). */
export const BrandSchema = v.looseObject({
  slug: id,
  name: str,
  shortName: opt(str),
  bundleId: str,
  scheme: v.pipe(str, v.regex(/^[a-z][a-z0-9+.-]*$/)),
  icon: str,
  logo: str,
  logoDark: opt(str),
  colors: v.looseObject({ primary: color, primaryContrast: color, accent: color }),
  defaultSite: v.nullable(str),
  lockSite: v.boolean(),
  loginMethods: v.array(v.picklist(['oauth', 'otp', 'apikey', 'apppass'])),
  defaultLocale: str,
  locales: v.array(str),
  oauthClientId: opt(str),
  ios: opt(v.looseObject({ bundleIdentifier: str, appleTeamId: opt(v.nullable(str)) })),
  android: opt(v.looseObject({ package: v.pipe(str, v.regex(/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/)) })),
  mobile: opt(v.looseObject({ scheme: opt(str), oauthClientId: opt(str), loginMethods: opt(v.array(v.picklist(['oauth', 'otp', 'apikey', 'apppass']))) })),
  allowedSites: opt(v.array(str)),
  locked: opt(v.array(str)),
});

// ---- parse helpers ----

export interface ParseIssue {
  where: string;
  message: string;
}

const issuesOf = (prefix: string, r: { issues: readonly v.BaseIssue<unknown>[] }): ParseIssue[] =>
  r.issues.map((i) => ({ where: prefix + (i.path ? '.' + i.path.map((p) => String(p.key)).join('.') : ''), message: i.message }));

/**
 * Desktop configs (`shell.sidebar` + a short `topbar`) omit the mobile-required keys. Fill those
 * from the sidebar so the existing schema still accepts them. Unknown keys (`sidebar`, `commands`)
 * stay on the object — ShellSchema is a loose object.
 */
function adaptConfig(input: unknown): unknown {
  if (!input || typeof input !== 'object') return input;
  const root = input as Record<string, unknown>;
  if (!root.shell || typeof root.shell !== 'object') return input;
  const s = { ...(root.shell as Record<string, unknown>) };
  let changed = false;
  const fill = (key: string, value: unknown) => {
    if (s[key] === undefined) {
      s[key] = value;
      changed = true;
    }
  };
  const side = s.sidebar && typeof s.sidebar === 'object' ? (s.sidebar as Record<string, unknown>) : null;
  fill('nav', side ? 'drawer' : 'tabs+drawer');
  fill('home', 'screen:core/dashboard');
  fill('tabs', []);
  fill('drawer', {
    enabled: true,
    header: 'account',
    pins: side?.pins ?? [],
    groups: side?.groups ?? [],
    footer: side?.footer ?? ['accounts', 'settings'],
  });
  if (s.topbar && typeof s.topbar === 'object') {
    const t = { ...(s.topbar as Record<string, unknown>) };
    let topChanged = false;
    for (const [k, v] of Object.entries({ style: 'compact', show_logo: true, site_switcher: true, actions: [] as unknown[] })) {
      if (t[k] === undefined) {
        t[k] = v;
        topChanged = true;
      }
    }
    if (topChanged) {
      s.topbar = t;
      changed = true;
    }
  } else fill('topbar', { style: 'compact', show_logo: true, site_switcher: true, actions: [] });
  if (s.drawer && typeof s.drawer === 'object') {
    const d = { ...(s.drawer as Record<string, unknown>) };
    let drawerChanged = false;
    for (const [k, v] of Object.entries({ enabled: true, header: 'account', groups: [] as unknown[], footer: [] as unknown[] })) {
      if (d[k] === undefined) {
        d[k] = v;
        drawerChanged = true;
      }
    }
    if (drawerChanged) {
      s.drawer = d;
      changed = true;
    }
  }
  return changed ? { ...root, shell: s } : input;
}

/** Full config (server output). Null when invalid: the caller keeps the app default. */
export function parseConfig(input: unknown, issues?: ParseIssue[]): AppConfig | null {
  const r = v.safeParse(ConfigSchema, adaptConfig(input));
  if (r.success) return r.output as unknown as AppConfig;
  issues?.push(...issuesOf('config', r));
  return null;
}

export function parseManifest(input: unknown, issues?: ParseIssue[]): Manifest | null {
  const r = v.safeParse(ManifestSchema, input);
  if (r.success) return r.output as unknown as Manifest;
  issues?.push(...issuesOf(`manifest:${(input as { id?: string })?.id ?? '?'}`, r));
  return null;
}

/** GET flxapp/v1/manifest → only the valid modules (keyed by their own id). */
export function parseManifestBundle(input: unknown, issues?: ParseIssue[]): ManifestBundle {
  const r = v.safeParse(ManifestBundleSchema, input);
  const modules: ManifestBundle['modules'] = {};
  if (!r.success) return { modules };
  for (const [key, raw] of Object.entries(r.output.modules)) {
    const m = parseManifest(raw, issues);
    if (m && m.id === key) modules[key] = m;
  }
  return { hash: r.output.hash, modules };
}

export function parseBootstrap(input: unknown): Bootstrap | null {
  const r = v.safeParse(BootstrapSchema, input);
  return r.success ? (r.output as unknown as Bootstrap) : null;
}
